import type { Editor } from "@tiptap/vue-3";
import { computed, inject, unref } from "vue";
import type { ComputedRef, InjectionKey, MaybeRefOrGetter } from "vue";

import { DEFAULT_EXTENSION_LABELS } from "./core-labels";
import type { ExtensionLabels } from "./core-labels";

export interface ToolbarContextValue {
  editor: ComputedRef<Editor | null>;
  labels: ComputedRef<ExtensionLabels>;
}

export const toolbarKey: InjectionKey<ToolbarContextValue> =
  Symbol("ExtensionToolbar");

const fallback: ToolbarContextValue = {
  editor: computed(() => null),
  labels: computed(() => DEFAULT_EXTENSION_LABELS),
};

export const useToolbar = (): ToolbarContextValue =>
  inject(toolbarKey, fallback);

export const useToolbarEditor = (
  editor: MaybeRefOrGetter<Editor | null | undefined>
): ComputedRef<Editor | null> => {
  const context = useToolbar();
  return computed(() => unref(toValueSafe(editor)) ?? context.editor.value);
};

// `unref` does not call getters; this keeps `() => props.editor` working.
const toValueSafe = <T>(value: MaybeRefOrGetter<T>): T =>
  typeof value === "function" ? (value as () => T)() : unref(value);

export interface ExtensionLabels {
  addColumnLeft: string;
  addColumnRight: string;
  addRowAbove: string;
  addRowBelow: string;
  columnActions: string;
  columns: string;
  deleteColumn: string;
  deleteRow: string;
  deleteTable: string;
  headerRow: string;
  image: string;
  imagePlaceholder: string;
  insertTable: string;
  mergeCells: string;
  rowActions: string;
  rows: string;
  splitCell: string;
  tableActions: string;
  video: string;
  videoPlaceholder: string;
}

export type ExtensionLabelKey = keyof ExtensionLabels;

export const DEFAULT_EXTENSION_LABELS: ExtensionLabels = {
  addColumnLeft: "Insert Left",
  addColumnRight: "Insert Right",
  addRowAbove: "Insert Above",
  addRowBelow: "Insert Below",
  columnActions: "Column actions",
  columns: "Columns",
  deleteColumn: "Delete column",
  deleteRow: "Delete row",
  deleteTable: "Delete table",
  headerRow: "Header row",
  image: "Image",
  imagePlaceholder: "Add an image",
  insertTable: "Insert table",
  mergeCells: "Merge cells",
  rowActions: "Row actions",
  rows: "Rows",
  splitCell: "Split cell",
  tableActions: "Table actions",
  video: "Video",
  videoPlaceholder: "Add a video",
};

import type { Editor } from "@tiptap/vue-3";

export interface ToolbarComponentProps {
  class?: string;
  editor?: Editor | null;
  size?: "icon" | "icon-lg" | "icon-sm";
}

import type { ChainedCommands } from "@tiptap/core";
import type { Editor } from "@tiptap/vue-3";

export const chainFocus = (editor: Editor): ChainedCommands =>
  editor.chain().focus();

export const isValidUrl = (url: string): boolean => /^https?:\/\/\S+$/.test(url);

export const extensionPresent = (
  editor: Editor | null,
  name: string
): boolean =>
  Boolean(
    editor &&
      !editor.isDestroyed &&
      editor.extensionManager.extensions.some(
        (extension) => extension.name === name
      )
  );

export const nodeActive = (
  editor: Editor | null,
  name: string,
  attributes?: Record<string, unknown>
): boolean =>
  Boolean(editor && !editor.isDestroyed && editor.isActive(name, attributes));

import Image from "@tiptap/extension-image";
import { VueNodeViewRenderer } from "@tiptap/vue-3";

import ResizableImageView from "./image-placeholder-image-view.vue";

export const ResizableImage = Image.extend({
  addAttributes() {
    return {
      align: { default: "center" },
      alt: { default: null },
      height: { default: null },
      src: { default: null },
      title: { default: null },
      width: { default: "100%" },
      /** CSS object-fit: contain | cover | fill | none | scale-down */
      objectFit: { default: "contain" },
    };
  },
  addNodeView() {
    return VueNodeViewRenderer(ResizableImageView);
  },
}).configure({ allowBase64: true });

import { mergeAttributes, Node } from "@tiptap/core";
import type { CommandProps, Editor } from "@tiptap/core";
import { VueNodeViewRenderer } from "@tiptap/vue-3";

import ImagePlaceholderNode from "./image-placeholder-image-placeholder-node.vue";
import type { UploadHandler } from "./upload";

export { ResizableImage } from "./image-placeholder-image";

export interface ImagePlaceholderOptions {
  HTMLAttributes: Record<string, unknown>;
  allowedMimeTypes?: Record<string, string[]>;
  maxFiles?: number;
  maxSize?: number;
  /**
   * Uploads a picked or dropped file and returns the image source.
   * Without it the placeholder falls back to a base64 data URL.
   */
  upload?: UploadHandler;
  onDrop?: (files: File[], editor: Editor) => void;
  onDropRejected?: (files: File[], editor: Editor) => void;
  onEmbed?: (url: string, editor: Editor) => void;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    imagePlaceholder: {
      insertImagePlaceholder: () => ReturnType;
    };
  }
}

export const ImagePlaceholder = Node.create<ImagePlaceholderOptions>({
  name: "imagePlaceholder",
  group: "block",
  atom: true,

  addOptions() {
    return {
      HTMLAttributes: {},
    };
  },

  addCommands() {
    return {
      insertImagePlaceholder:
        () =>
        ({ chain, state }: CommandProps) => {
          const { from } = state.selection;
          const node = this.type.create();
          return chain()
            .insertContentAt(from, node.toJSON())
            .setTextSelection(from + node.nodeSize)
            .run();
        },
    };
  },

  addNodeView() {
    return VueNodeViewRenderer(ImagePlaceholderNode);
  },

  parseHTML() {
    return [{ tag: `div[data-type="${this.name}"]` }];
  },

  renderHTML({ HTMLAttributes }) {
    return [
      "div",
      mergeAttributes(this.options.HTMLAttributes, HTMLAttributes, {
        "data-type": this.name,
      }),
    ];
  },
});

/* Image placeholder + resizable image extension styles using shadcn CSS variables */

/* ── Placeholder node ── */
.ext-image-placeholder {
  width: 100%;
}

.ext-image-placeholder .ext-popover {
  display: flex;
  width: 100%;
}

.ext-image-placeholder-trigger {
  display: flex;
  width: 100%;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem;
  border: none;
  border-radius: calc(var(--radius) - 2px);
  background: var(--accent);
  color: var(--accent-foreground);
  font-size: 0.875rem;
  font-family: inherit;
  text-align: left;
  cursor: pointer;
  transition:
    background-color 150ms ease-out,
    color 150ms ease-out,
    box-shadow 150ms ease-out;
}

.ext-image-placeholder-trigger > svg {
  width: 1.5rem;
  height: 1.5rem;
  flex-shrink: 0;
}

.ext-image-placeholder-trigger:hover {
  background: var(--secondary);
  color: var(--secondary-foreground);
}

.ext-image-placeholder-trigger--selected,
.ext-image-placeholder-trigger:focus-visible {
  outline: none;
  box-shadow: 0 0 0 2px var(--ring);
}

.ext-image-placeholder-popover {
  width: 28rem;
  max-width: min(calc(100vw - 2rem), 28rem);
  padding: 0.75rem;
}

.ext-image-upload-zone {
  margin: 0.5rem 0;
  border: 1px dashed var(--border);
  border-radius: calc(var(--radius) - 2px);
  font-size: 0.875rem;
  transition:
    border-color 150ms ease-out,
    background-color 150ms ease-out;
}

.ext-image-upload-zone:hover {
  background: var(--secondary);
}

.ext-image-upload-zone--dragging {
  border-color: var(--primary);
  background: var(--secondary);
}

.ext-image-upload-zone--reject {
  border-color: var(--destructive);
  background: color-mix(in srgb, var(--destructive) 10%, transparent);
}

.ext-image-upload-label {
  display: flex;
  height: 7rem;
  width: 100%;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  cursor: pointer;
  user-select: none;
}

.ext-image-upload-label > svg {
  width: 1.5rem;
  height: 1.5rem;
  margin: 0 auto 0.5rem;
  flex-shrink: 0;
}

.ext-image-embed {
  display: grid;
  gap: 0.5rem;
}

.ext-image-embed-submit.ext-image-embed-submit {
  width: 100%;
  border-color: transparent;
  background: var(--primary);
  color: var(--primary-foreground);
}

.ext-image-embed-submit.ext-image-embed-submit:hover {
  background: color-mix(in srgb, var(--primary) 85%, black);
  color: var(--primary-foreground);
}

.ext-image-error {
  margin: 0;
  font-size: 0.75rem;
  color: var(--destructive, #ef4444);
}

.ext-image-hint {
  margin: 0;
  text-align: center;
  font-size: 0.75rem;
  color: var(--muted-foreground);
}

.ext-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border-width: 0;
}

/* ── Resizable image node ── */
.ext-image-view {
  position: relative;
  display: flex;
  flex-direction: column;
  width: fit-content;
  margin-block: 1rem;
  border-radius: calc(var(--radius) - 2px);
}

.ext-image-view--left {
  margin-right: auto;
}

.ext-image-view--center {
  margin-inline: auto;
}

.ext-image-view--right {
  margin-left: auto;
}

.ext-image-view--selected {
  box-shadow: 0 0 0 2px var(--ring);
}

.ext-image-view-img {
  display: block;
  width: 100%;
  height: auto;
  border-radius: calc(var(--radius) - 2px);
}

.ext-image-view-caption {
  padding-top: 0.375rem;
  text-align: center;
  font-size: 0.875rem;
  color: var(--muted-foreground);
}

/* resize handles */
.ext-image-resize {
  position: absolute;
  top: 0;
  bottom: 0;
  z-index: 20;
  display: flex;
  align-items: center;
  width: 1rem;
  cursor: col-resize;
  touch-action: none;
}

.ext-image-resize--left {
  left: 0;
  justify-content: flex-start;
}

.ext-image-resize--right {
  right: 0;
  justify-content: flex-end;
}

.ext-image-resize-bar {
  width: 0.25rem;
  height: 4rem;
  border-radius: 999px;
  background: color-mix(in srgb, var(--foreground) 30%, transparent);
  opacity: 0;
  transition: opacity 150ms ease-out;
}

.ext-image-view:hover .ext-image-resize-bar,
.ext-image-view--resizing .ext-image-resize-bar {
  opacity: 1;
}

/* action bar — rendered in a portal (fixed) so it never gets clipped by
   overflow containers, tracked to the image's rect below/right of the node */
.ext-image-actions {
  display: flex;
  align-items: center;
  gap: 0.25rem;
  padding: 0.25rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  background: var(--popover);
  color: var(--popover-foreground);
  box-shadow: 0 4px 16px rgba(0, 0, 0, 0.08);
}

.ext-image-actions--floating {
  position: fixed;
  margin-top: 0;
  z-index: 60;
  opacity: 1;
}

.ext-image-action-btn {
  width: 1.75rem;
  padding: 0;
}

.ext-image-more-content {
  min-width: 11rem;
}

export { ImagePlaceholder, ResizableImage } from "./image-placeholder-index";
export type { ImagePlaceholderOptions } from "./image-placeholder-index";
export { default as ImagePlaceholderToolbar } from "./image-placeholder-toolbar.vue";
export { MediaUpload } from "./media-upload";
export type { MediaUploadOptions } from "./media-upload";
export { Video, VideoPlaceholder } from "./video-index";
export type { VideoOptions, VideoPlaceholderOptions } from "./video-index";
export { default as VideoToolbar } from "./video-toolbar.vue";
export type {
  UploadHandler,
  UploadKind,
  UploadResult,
} from "./upload";
export { Table } from "./table-index";
export type { TableConfigOptions } from "./table-index";
export { default as TableHoverOverlay } from "./table-hover-overlay.vue";
export { default as TableToolbar } from "./table-toolbar.vue";
export { default as ToolbarProvider } from "./core-provider.vue";
export { useToolbar, useToolbarEditor } from "./core-context";
export type { ExtensionLabels } from "./core-labels";
export { DEFAULT_EXTENSION_LABELS } from "./core-labels";
export { chainFocus, extensionPresent, isValidUrl, nodeActive } from "./core-utils";
export type { ToolbarComponentProps } from "./core-types";

import { Extension } from "@tiptap/core";
import { Plugin } from "@tiptap/pm/state";
import type { EditorView } from "@tiptap/pm/view";

import type { UploadHandler, UploadKind } from "./upload";

export interface MediaUploadOptions {
  /** Required: your upload implementation, shared with the placeholder blocks. */
  upload: UploadHandler;
  /** Reject files above this size in bytes. */
  maxSize?: number;
  /** Insert video nodes for `video/*` files. Defaults to true. */
  video?: boolean;
  /** Called for rejected or failed files so you can surface a toast. */
  onError?: (error: unknown, file: File) => void;
}

const isMediaFile = (file: File) =>
  file.type.startsWith("image/") || file.type.startsWith("video/");

/**
 * Pastes and drops straight into the editor: every image or video file goes
 * through the same `UploadHandler` used by the placeholder blocks.
 */
export const MediaUpload = Extension.create<MediaUploadOptions>({
  name: "mediaUpload",

  addOptions() {
    return {
      upload: async () => {
        throw new Error("MediaUpload needs an upload handler");
      },
      video: true,
    };
  },

  addProseMirrorPlugins() {
    const { upload, maxSize, onError } = this.options;
    const allowVideo = this.options.video !== false;
    const editor = this.editor;

    const supports = (name: string) =>
      editor.extensionManager.extensions.some(
        (extension) => extension.name === name
      );

    const insertFiles = async (
      files: File[],
      position?: number
    ): Promise<void> => {
      for (const file of files) {
        if (maxSize && file.size > maxSize) {
          onError?.(new Error(`File is larger than ${maxSize} bytes`), file);
          continue;
        }

        const kind: UploadKind = file.type.startsWith("video/")
          ? "video"
          : "image";
        if (kind === "video" && (!allowVideo || !supports("video"))) {
          continue;
        }
        if (kind === "image" && !supports("image")) {
          continue;
        }

        try {
          const result = await upload(file, kind);
          const node =
            kind === "video"
              ? {
                  attrs: {
                    poster: result.poster ?? null,
                    src: result.src,
                    width: result.width ?? "100%",
                  },
                  type: "video",
                }
              : {
                  attrs: {
                    alt: result.alt ?? null,
                    height: result.height ?? null,
                    src: result.src,
                    width: result.width ?? "60%",
                  },
                  type: "image",
                };

          const chain = editor.chain().focus();
          if (typeof position === "number") {
            chain.insertContentAt(position, node).run();
            // keep subsequent files after the inserted node
            position += 1;
          } else {
            chain.insertContent(node).run();
          }
        } catch (error) {
          onError?.(error, file);
        }
      }
    };

    const filesFrom = (list: FileList | null | undefined): File[] =>
      [...(list ?? [])].filter(isMediaFile);

    return [
      new Plugin({
        props: {
          handlePaste: (_view: EditorView, event: ClipboardEvent) => {
            const files = filesFrom(event.clipboardData?.files);
            if (files.length === 0) {
              return false;
            }
            event.preventDefault();
            void insertFiles(files);
            return true;
          },

          handleDrop: (
            view: EditorView,
            event: DragEvent,
            _slice: unknown,
            moved: boolean
          ) => {
            if (moved) {
              return false;
            }
            const files = filesFrom(event.dataTransfer?.files);
            if (files.length === 0) {
              return false;
            }
            event.preventDefault();
            const coords = view.posAtCoords({
              left: event.clientX,
              top: event.clientY,
            });
            void insertFiles(files, coords?.pos);
            return true;
          },
        },
      }),
    ];
  },
});

import type { CommandProps } from "@tiptap/core";
import { Gapcursor } from "@tiptap/extension-gapcursor";
import {
  Table as TiptapTable,
  TableCell,
  TableHeader,
  TableRow,
} from "@tiptap/extension-table";

export interface TableConfigOptions {
  HTMLAttributes?: Record<string, unknown>;
  defaultCols?: number;
  defaultRows?: number;
  tableCellMinWidth?: number;
  withHeaderRow?: boolean;
  resizable?: boolean;
}

declare module "@tiptap/core" {
  interface Commands<ReturnType> {
    tableControl: {
      insertTableWithHeader: () => ReturnType;
      moveColumn: (from: number, to: number) => ReturnType;
      moveRow: (from: number, to: number) => ReturnType;
    };
  }
}

const clampIndex = (index: number, length: number): number =>
  Math.max(0, Math.min(index, length - 1));

const findTablePosition = (doc: {
  descendants: (
    cb: (node: { type: { name: string } }, pos: number) => boolean | undefined
  ) => void;
}): number => {
  let position = -1;
  doc.descendants((node, pos) => {
    if (position !== -1 || node.type.name !== "table") {
      return position === -1;
    }
    position = pos;
    return false;
  });
  return position;
};

export const Table = TiptapTable.extend<TableConfigOptions>({
  addCommands() {
    return {
      ...this.parent?.(),
      insertTableWithHeader:
        () =>
        ({ commands }: CommandProps) =>
          commands.insertTable({
            cols: this.options.defaultCols ?? 3,
            rows: this.options.defaultRows ?? 3,
            withHeaderRow: this.options.withHeaderRow ?? true,
          }),
      moveColumn:
        (from: number, to: number) =>
        ({ dispatch, state }: CommandProps) => {
          const tablePos = findTablePosition(state.doc);
          if (tablePos === -1 || from === to) {
            return false;
          }
          const table = state.doc.nodeAt(tablePos);
          if (!table) {
            return false;
          }

          const columnCount = table.child(0)?.childCount ?? 0;
          const source = clampIndex(from, columnCount);
          const target = clampIndex(to, columnCount);
          if (source === target) {
            return false;
          }

          const rows = [];
          for (let r = 0; r < table.childCount; r += 1) {
            const row = table.child(r);
            const cells = [];
            for (let c = 0; c < row.childCount; c += 1) {
              cells.push(row.child(c));
            }
            if (cells.length === 0 || source >= cells.length) {
              rows.push(row);
              continue;
            }
            const [moved] = cells.splice(source, 1);
            if (moved === undefined) {
              rows.push(row);
              continue;
            }
            const clampedTarget = Math.min(target, cells.length);
            cells.splice(clampedTarget, 0, moved);
            rows.push(row.type.create(row.attrs, cells));
          }

          const { tr } = state;
          tr.replaceWith(
            tablePos,
            tablePos + table.nodeSize,
            table.type.create(table.attrs, rows)
          );
          dispatch?.(tr);
          return true;
        },
      moveRow:
        (from: number, to: number) =>
        ({ dispatch, state }: CommandProps) => {
          const tablePos = findTablePosition(state.doc);
          if (tablePos === -1 || from === to) {
            return false;
          }
          const table = state.doc.nodeAt(tablePos);
          if (!table) {
            return false;
          }

          const source = clampIndex(from, table.childCount);
          const target = clampIndex(to, table.childCount);
          if (source === target) {
            return false;
          }

          const rows = [];
          for (let r = 0; r < table.childCount; r += 1) {
            rows.push(table.child(r));
          }
          const [moved] = rows.splice(source, 1);
          if (moved === undefined) {
            return false;
          }
          rows.splice(target, 0, moved);

          const { tr } = state;
          tr.replaceWith(
            tablePos,
            tablePos + table.nodeSize,
            table.type.create(table.attrs, rows)
          );
          dispatch?.(tr);
          return true;
        },
    };
  },
  addExtensions() {
    return [TableRow, TableCell, TableHeader, Gapcursor];
  },
  addOptions() {
    return {
      ...this.parent?.(),
      defaultCols: 3,
      defaultRows: 3,
      resizable: true,
      withHeaderRow: true,
    };
  },
});

/* Table extension styles using shadcn CSS variables */

/* ── Hover overlay ──
   The overlay is a zero-size origin box: the controls are absolutely positioned
   and measured against it every frame. Keeping it zero-size means the handles
   never take part in layout.

   The inner clip box is sized and positioned to the editor's visible box every
   frame and clips the handles to it, so a table scrolled out of view cannot
   leave handles floating over the surrounding UI. Clipping here rather than on
   the editor's own wrapper keeps the editor's bubble menu and drag handle
   intact. */
.ext-table-overlay {
  position: absolute;
  left: 0;
  top: 0;
  width: 0;
  height: 0;
  overflow: visible;
}

.ext-table-clip {
  position: absolute;
  overflow: hidden;
  pointer-events: none;
}

/* The handles stay interactive even though the clip box ignores pointer
   events, so hovering a handle still reaches the editor's pointer handlers. */
.ext-table-control,
.ext-table-add {
  pointer-events: auto;
}

/* ── Table node view wrapper ──
   Tiptap's Table View renders a <div class="tableWrapper"> around the
   <table>. We use it as the hover container (grips stay visible anywhere
   inside it) and as the horizontal scroll container so wide tables with
   many columns scroll instead of overflowing the content area. */
.tableWrapper {
  position: relative;
  overflow-x: auto;
  overflow-y: hidden;
  padding-bottom: 0.375rem;
  scrollbar-width: thin;
}

/* Columns must keep their widths when a column is added/removed. If the table
   fills the container (`width: 100%` + auto columns), the browser re-distributes
   the fixed width across more columns and they all shrink. Instead we size the
   table to its columns (`width: max-content`) so each column keeps its declared
   width and an inserted column extends the row width — the `.tableWrapper`
   scroll container above then shows the horizontal scrollbar instead. */
.tableWrapper > table {
  border-collapse: collapse;
  table-layout: fixed;
  width: max-content;
}

/* Stable default width for columns until the user resizes them (resize writes
   an inline width, which overrides this). Prevents fixed-layout auto columns
   from collapsing to 0 / splitting the table width on insert. */
.tableWrapper > table > colgroup > col {
  width: 8rem;
}

/* ── Cell borders & header row ── */
.ProseMirror table {
  border-collapse: collapse;
  margin: 0;
  overflow: hidden;
  position: relative;
}

.ProseMirror td,
.ProseMirror th {
  border: 1px solid var(--border);
  padding: 0.5rem 0.75rem;
  vertical-align: top;
  text-align: left;
  min-width: 80px;
  position: relative;
}

.ProseMirror th {
  background: var(--muted);
  font-weight: 600;
}

.ProseMirror .selectedCell {
  background: var(--accent);
}

.ext-table-control {
  position: absolute;
  z-index: 2;
  animation: ext-table-pop-in 0.18s cubic-bezier(0.22, 1, 0.36, 1) forwards;
}

.ext-table-control--column {
  transform-origin: top center;
}

.ext-table-control--row {
  transform-origin: center left;
}

.ext-table-grip {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 1.1rem;
  height: 1.1rem;
  padding: 0;
  border: 1px solid transparent;
  border-radius: calc(var(--radius) - 4px);
  background: transparent;
  color: var(--muted-foreground);
  cursor: pointer;
  touch-action: none;
  box-shadow: none;
  transition:
    background-color 150ms ease-out,
    border-color 150ms ease-out,
    box-shadow 150ms ease-out,
    color 150ms ease-out;
}

.ext-table-grip::before {
  content: "";
